<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/schema_helpers.php';if(session_status()===PHP_SESSION_NONE)session_start();
$formId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;if(!$formId){http_response_code(400);exit('Thiếu mã biểu mẫu.');}requireFormManager($pdo,$formId);
$q=$pdo->prepare('SELECT title FROM forms WHERE id=?');$q->execute([$formId]);$title=$q->fetchColumn();if(!$title){http_response_code(404);exit('Không tìm thấy biểu mẫu.');}
$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST') { $uid=(int)($_POST['user_id']??0);$view=isset($_POST['can_view'])?1:0;$export=isset($_POST['can_export'])?1:0;try{if(!$uid)throw new RuntimeException('Chọn tài khoản cần cấp quyền.');$q=$pdo->prepare('SELECT id FROM users WHERE id=?');$q->execute([$uid]);if(!$q->fetchColumn())throw new RuntimeException('Tài khoản không tồn tại.');if(!$view&&!$export){$q=$pdo->prepare('DELETE FROM form_permissions WHERE form_id=? AND user_id=?');$q->execute([$formId,$uid]);}else{$q=$pdo->prepare('INSERT INTO form_permissions(form_id,user_id,can_view,can_export) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE can_view=VALUES(can_view),can_export=VALUES(can_export)');$q->execute([$formId,$uid,$view,$export]);}$ok='Đã cập nhật quyền.';}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Không thể cập nhật quyền. Kiểm tra bảng form_permissions.';}}
$users=$pdo->query('SELECT id,username,full_name,role FROM users ORDER BY full_name')->fetchAll();$q=$pdo->prepare('SELECT p.*,u.username,u.full_name FROM form_permissions p JOIN users u ON u.id=p.user_id WHERE p.form_id=? ORDER BY u.full_name');$q->execute([$formId]);$grants=$q->fetchAll();function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phân quyền biểu mẫu</title><link rel="stylesheet" href="assets/form_builder.css"><style>body{background:#f6f5fb;font-family:Arial}.wrap{max-width:900px;margin:35px auto;padding:20px}.panel{background:white;padding:24px;border-radius:16px;margin-top:18px}.row{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin:12px 0}select,button{padding:10px;border:1px solid #ddd;border-radius:8px}.notice{padding:12px;margin:12px 0;border-radius:8px}.ok{background:#e8f8ed}.err{background:#fff0f0}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #eee}</style></head><body><main class="wrap"><a href="form_builder.php?id=<?=$formId?>">← Quay lại thiết kế</a><h1>Phân quyền xem và xuất dữ liệu</h1><p>Biểu mẫu: <b><?=h($title)?></b></p><?php if($ok):?><div class="notice ok"><?=h($ok)?></div><?php endif;?><?php if($error):?><div class="notice err"><?=h($error)?></div><?php endif;?><section class="panel"><h2>Cấp quyền cho tài khoản</h2><form method="post"><div class="row"><label>Tài khoản <select name="user_id" required><option value="">-- Chọn --</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=h($u['full_name'].' ('.$u['username'].') · '.$u['role'])?></option><?php endforeach;?></select></label></div><div class="row"><label><input type="checkbox" name="can_view" value="1"> Được xem câu trả lời</label><label><input type="checkbox" name="can_export" value="1"> Được xuất CSV</label></div><button type="submit">Lưu quyền</button><p><small>Bỏ chọn cả hai quyền rồi lưu sẽ xóa quyền đã cấp.</small></p></form></section><section class="panel"><h2>Quyền hiện tại</h2><table><thead><tr><th>Tài khoản</th><th>Xem</th><th>Xuất</th></tr></thead><tbody><?php foreach($grants as $g):?><tr><td><?=h($g['full_name'].' ('.$g['username'].')')?></td><td><?=$g['can_view']?'Có':'Không'?></td><td><?=$g['can_export']?'Có':'Không'?></td></tr><?php endforeach;?><?php if(!$grants):?><tr><td colspan="3">Chưa cấp quyền cho tài khoản nào.</td></tr><?php endif;?></tbody></table></section></main></body></html>
